CREATE TABLE IF NOT EXISTS data_flow_metrics AS
SELECT recordregistry, flowstamp, flowtag, orignation, destnation, origactor, destactor, chanproto, chanfreq, datasizemb, durmin, bwidthpct, successpct, errtally, rtrytally, successpct / (errtally + 1.0) AS data_transfer_efficiency
FROM dataflow;

CREATE TABLE IF NOT EXISTS data_flow_metrics (
    recordregistry CHAR(10) PRIMARY KEY,
    data_transfer_efficiency NUMERIC(10,4)
);

INSERT INTO data_flow_metrics (recordregistry, data_transfer_efficiency)
SELECT recordregistry, successpct / (errtally + 1.0) AS data_transfer_efficiency
FROM dataflow;

CREATE TABLE IF NOT EXISTS data_flow_metrics (
    recordregistry CHAR(10) PRIMARY KEY,
    data_transfer_efficiency NUMERIC
);

INSERT INTO data_flow_metrics
SELECT recordregistry, successpct / (errtally + 1.0)
FROM dataflow;

CREATE TABLE IF NOT EXISTS data_flow_metrics AS SELECT * FROM dataflow;

ALTER TABLE data_flow_metrics ADD COLUMN data_transfer_efficiency NUMERIC;

UPDATE data_flow_metrics SET data_transfer_efficiency = successpct / (errtally + 1.0);
